INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Nachhaltigkeit in der IT nur den Energieverbrauch betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch soziale und wirtschaftliche Aspekte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Nachhaltigkeit in einem IT-Projekt umsetze?', 3, '[{"text": "Energieeffizienz", "correct": true, "because": "Reduziert Umweltbelastung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Langfristigkeit zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zur Nachhaltigkeit in der IT?', 5, '[{"text": "Energieverbrauch", "correct": true, "because": "Ökologischer Faktor"}, {"text": "Ressourcenschonung", "correct": true, "because": "Wirtschaftlicher Faktor"}, {"text": "Büromöbel", "correct": false, "because": "Kein Nachhaltigkeitsfaktor"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nachhaltigkeit in der IT reduziert CO₂-Emissionen. b) Sie ist immer teurer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten können sinken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Nachhaltigkeit in einem IT-Projekt plane?', 4, '[{"text": "Energieverbrauch", "correct": false, "because": "Wichtiger Faktor"}, {"text": "Recycling", "correct": false, "because": "Ressourcenschonung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Nachhaltigkeitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Nachhaltigkeit in der IT nur ökologische Aspekte umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch sozial und wirtschaftlich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Nachhaltigkeit in einem IT-System?', 3, '[{"text": "Umweltfreundlichkeit", "correct": true, "because": "Reduziert Belastung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Langfristigkeit zählt"}, {"text": "Weniger Funktionen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern Nachhaltigkeit in der IT?', 5, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Senkt Verbrauch"}, {"text": "Recycling von Geräten", "correct": true, "because": "Schont Ressourcen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Nachhaltigkeit in der IT kann Kosten senken. b) Sie ist immer unwirtschaftlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann wirtschaftlich sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Nachhaltigkeit in einem IT-Projekt umzusetzen?', 4, '[{"text": "Energieanalyse", "correct": false, "because": "Misst Verbrauch"}, {"text": "Recyclingplan", "correct": false, "because": "Schont Ressourcen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Nachhaltigkeitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Nachhaltigkeit in der IT immer teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Kann Kosten senken"}, {"text": "Ja", "correct": false, "because": "Abhängig von Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Nachhaltigkeit in der IT?', 4, '[{"text": "Geringerer Energieverbrauch", "correct": true, "because": "Schont Umwelt"}, {"text": "Besseres Image", "correct": true, "because": "Fördert Reputation"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Nachhaltigkeit in der IT nur Hardware betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Prozesse"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Nachhaltigkeit in einem IT-Projekt zu fördern?', 3, '[{"text": "Effiziente Technologien", "correct": true, "because": "Senken Verbrauch"}, {"text": "Schnellste Hardware", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Bunte Kabel", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nachhaltigkeit in der IT schont Ressourcen. b) Sie ist immer unwirtschaftlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann wirtschaftlich sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Nachhaltigkeit in der IT?', 5, '[{"text": "Energieverbrauch", "correct": true, "because": "Ökologischer Faktor"}, {"text": "Lebenszyklus", "correct": true, "because": "Ressourcennutzung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Nachhaltigkeit in einem IT-Projekt plane?', 3, '[{"text": "Recycling", "correct": false, "because": "Schont Ressourcen"}, {"text": "Energieeffizienz", "correct": false, "because": "Reduziert Verbrauch"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Nachhaltigkeitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Betrifft Nachhaltigkeit in der IT nur die Hardware?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Software und Prozesse"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Nachhaltigkeit in der IT nur ökologische Vorteile bietet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch wirtschaftlich und sozial"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Nachhaltigkeit in der IT?', 4, '[{"text": "Energieeffizienz", "correct": true, "because": "Reduziert Umweltbelastung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Langfristigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
